    [Xunit.Fact]
    public static void TestAttributesSetReplaceAndRepeat() {
        emon.Port.Cells nodes = emon.Port.NewCells();
        emon.Port.Cells attrs = emon.Port.NewCells();
        emon.Port.Cells regions = emon.Port.NewCells();
        emon.Port.Cells text = emon.Port.NewCells();
        emon.Port.Cells pages = emon.Port.NewCells();
        emon.Port.Cells ledger = emon.Port.NewCells();
        emon.Port.Cells layout = emon.Port.NewCells();
        int a = 0;
        MtTree(nodes, attrs, regions, text, pages, ledger, layout);
        MtText(text, 20);
        emon.Testport.AssertEq(Model.NodeAttr(nodes, attrs, 2, Model.FkLevel()), -1, "no attribute yet");
        emon.Testport.AssertEq(Model.NodeAttrIntOr(nodes, attrs, 2, Model.FkLevel(), 77), 77, "default when absent");
        Model.NodeSetAttrInt(nodes, attrs, 2, Model.FkLevel(), 4);
        Model.NodeSetAttrText(nodes, attrs, 2, Model.FkLabel(), 10, 6);
        Model.NodeSetAttrNode(nodes, attrs, 2, Model.FkTarget(), 7);
        Model.NodeSetAttrBool(nodes, attrs, 2, Model.FkChecked(), 5);
        emon.Testport.AssertEq(Model.AttrCount(attrs), 4, "four attributes");
        emon.Testport.AssertEq(Model.NodeAttrHead(nodes, 2), 0, "head is the first");
        a = Model.NodeAttr(nodes, attrs, 2, Model.FkLabel());
        emon.Testport.AssertEq(a, 1, "label is attr 1");
        emon.Testport.AssertEq(Model.AttrKey(attrs, a), Model.FkLabel(), "key");
        emon.Testport.AssertEq(Model.AttrVkind(attrs, a), Model.AvText(), "a text value");
        emon.Testport.AssertEq(Model.AttrValue(attrs, a), 10, "run start");
        emon.Testport.AssertEq(Model.AttrLen(attrs, a), 6, "run length");
        emon.Testport.AssertEq(Model.AttrNext(attrs, a), 2, "chain order is insertion order");
        a = Model.NodeAttr(nodes, attrs, 2, Model.FkTarget());
        emon.Testport.AssertEq(Model.AttrVkind(attrs, a), Model.AvNode(), "a node value");
        emon.Testport.AssertEq(Model.AttrValue(attrs, a), 7, "target node");
        a = Model.NodeAttr(nodes, attrs, 2, Model.FkChecked());
        emon.Testport.AssertEq(Model.AttrVkind(attrs, a), Model.AvBool(), "a bool value");
        emon.Testport.AssertEq(Model.AttrValue(attrs, a), 1, "non-zero is stored as 1");
        emon.Testport.AssertEq(Model.AttrNext(attrs, a), -1, "the chain ends");
        Model.NodeSetAttrInt(nodes, attrs, 2, Model.FkLevel(), 5);
        emon.Testport.AssertEq(Model.AttrCount(attrs), 4, "set replaced in place");
        emon.Testport.AssertEq(Model.NodeAttrIntOr(nodes, attrs, 2, Model.FkLevel(), 77), 5, "the new value");
        Model.NodeSetAttrText(nodes, attrs, 2, Model.FkLevel(), 3, 2);
        emon.Testport.AssertEq(Model.AttrVkind(attrs, 0), Model.AvText(), "set may change the value kind");
        emon.Testport.AssertEq(Model.AttrLen(attrs, 0), 2, "and the length");
        Model.NodeSetAttrBool(nodes, attrs, 2, Model.FkChecked(), 0);
        emon.Testport.AssertEq(Model.NodeAttrIntOr(nodes, attrs, 2, Model.FkChecked(), 9), 0, "false is 0");
        Model.NodeAddAttrInt(nodes, attrs, 7, Model.FkPages(), 1);
        Model.NodeAddAttrInt(nodes, attrs, 7, Model.FkPages(), 2);
        Model.NodeAddAttrInt(nodes, attrs, 7, Model.FkPages(), 9);
        Model.NodeAddAttrText(nodes, attrs, 7, Model.FkLabels(), 0, 1);
        emon.Testport.AssertEq(Model.AttrCount(attrs), 8, "add always appends");
        a = Model.NodeAttr(nodes, attrs, 7, Model.FkPages());
        emon.Testport.AssertEq(Model.AttrValue(attrs, a), 1, "first of the repeated key");
        a = Model.AttrFindNext(attrs, a, Model.FkPages());
        emon.Testport.AssertEq(Model.AttrValue(attrs, a), 2, "second");
        a = Model.AttrFindNext(attrs, a, Model.FkPages());
        emon.Testport.AssertEq(Model.AttrValue(attrs, a), 9, "third");
        emon.Testport.AssertEq(Model.AttrFindNext(attrs, a, Model.FkPages()), -1, "no fourth");
        emon.Testport.AssertEq(Model.NodeAttr(nodes, attrs, 7, Model.FkAlt()), -1, "a key never set");
        emon.Testport.AssertEq(Model.NodeAttr(nodes, attrs, 3, Model.FkPages()), -1, "another node's chain is its own");
        emon.Testport.AssertEq(Model.ModelCheck(nodes, attrs, regions, text, pages, ledger, layout, emon.Port.NewCells()), 0, "well formed");
    }
    [Xunit.Fact]
    public static void TestTextArenaHoldsScalarValuesOnly() {
        emon.Port.Cells text = emon.Port.NewCells();
        emon.Testport.AssertEq(Model.TextAppendCp(text, 72), 0, "index written");
        emon.Testport.AssertEq(Model.TextAppendCp(text, 233), 1, "index written");
        Model.TextAppendCp(text, 128512);
        Model.TextAppendCp(text, -1);
        Model.TextAppendCp(text, 55296);
        Model.TextAppendCp(text, 57343);
        Model.TextAppendCp(text, 1114111);
        Model.TextAppendCp(text, 1114112);
        Model.TextAppendCp(text, 0);
        emon.Testport.AssertEq(Model.TextLen(text), 9, "nine cells");
        emon.Testport.AssertEq(Model.TextAt(text, 0), 72, "H");
        emon.Testport.AssertEq(Model.TextAt(text, 1), 233, "e acute");
        emon.Testport.AssertEq(Model.TextAt(text, 2), 128512, "a code point past the BMP is one cell");
        emon.Testport.AssertEq(Model.TextAt(text, 3), 65533, "negative becomes U+FFFD");
        emon.Testport.AssertEq(Model.TextAt(text, 4), 65533, "a high surrogate becomes U+FFFD");
        emon.Testport.AssertEq(Model.TextAt(text, 5), 65533, "a low surrogate becomes U+FFFD");
        emon.Testport.AssertEq(Model.TextAt(text, 6), 1114111, "U+10FFFF is kept");
        emon.Testport.AssertEq(Model.TextAt(text, 7), 65533, "past U+10FFFF becomes U+FFFD");
        emon.Testport.AssertEq(Model.TextAt(text, 8), 0, "NUL is a scalar value");
    }
    [Xunit.Fact]
    public static void TestUtf8ValidAndInvalidSequences() {
        emon.Port.Cells text = emon.Port.NewCells();
        int n = Model.TextAppendUtf8(text, emon.Testport.HexBlob("41c3a9e282acf09f988080c0e080eda080f4908080 41"), 0, 22);
        emon.Testport.AssertEq(n, 16, "sixteen code points: four good, eleven replacements, one more");
        emon.Testport.AssertEq(Model.TextLen(text), 16, "and sixteen cells");
        emon.Testport.AssertEq(Model.TextAt(text, 0), 65, "ASCII");
        emon.Testport.AssertEq(Model.TextAt(text, 1), 233, "two bytes");
        emon.Testport.AssertEq(Model.TextAt(text, 2), 8364, "three bytes");
        emon.Testport.AssertEq(Model.TextAt(text, 3), 128512, "four bytes");
        emon.Testport.AssertEq(Model.TextAt(text, 4), 65533, "a stray continuation byte");
        emon.Testport.AssertEq(Model.TextAt(text, 5), 65533, "C0 is never a lead");
        emon.Testport.AssertEq(Model.TextAt(text, 6), 65533, "E0 followed by 80 is overlong: E0 is one replacement");
        emon.Testport.AssertEq(Model.TextAt(text, 7), 65533, "and the 80 is a stray");
        emon.Testport.AssertEq(Model.TextAt(text, 8), 65533, "ED A0 is a surrogate: ED is one replacement");
        emon.Testport.AssertEq(Model.TextAt(text, 9), 65533, "A0 is a stray");
        emon.Testport.AssertEq(Model.TextAt(text, 10), 65533, "80 is a stray");
        emon.Testport.AssertEq(Model.TextAt(text, 11), 65533, "F4 90 is past U+10FFFF: F4 is one replacement");
        emon.Testport.AssertEq(Model.TextAt(text, 12), 65533, "90 is a stray");
        emon.Testport.AssertEq(Model.TextAt(text, 13), 65533, "80 is a stray");
        emon.Testport.AssertEq(Model.TextAt(text, 14), 65533, "80 is a stray");
        emon.Testport.AssertEq(Model.TextAt(text, 15), 65, "decoding resumes");
    }
    [Xunit.Fact]
    public static void TestUtf8TruncationAndSpans() {
        emon.Port.Cells text = emon.Port.NewCells();
        int n1 = Model.TextAppendUtf8(text, emon.Testport.HexBlob("41e282"), 0, 3);
        int n2 = Model.TextAppendUtf8(text, emon.Testport.HexBlob("41c3a942"), 1, 3);
        int n3 = Model.TextAppendUtf8(text, emon.Testport.HexBlob("f09f98"), 0, 3);
        int n4 = Model.TextAppendUtf8(text, emon.Testport.HexBlob("f09f9880"), 0, 0);
        emon.Testport.AssertEq(n1, 2, "A, then a cut-short three-byte sequence is one replacement");
        emon.Testport.AssertEq(n2, 1, "the span is [1,3): just the two bytes of e acute");
