        emon.Testport.AssertEq(Model.TextAt(text, 1), 65533, "replacement");
        emon.Testport.AssertEq(Model.TextAt(text, 2), 233, "e acute");
        emon.Testport.AssertEq(Model.TextAt(text, 3), 65533, "replacement");
    }
