    internal static int MtTiny(emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells text, emon.Port.Cells pages, emon.Port.Cells ledger, emon.Port.Cells layout) {
        Model.ModelInit(nodes, attrs, regions, text, pages, ledger, layout);
        Model.NodeNew(nodes, Model.NkParagraph(), 0);
        Model.TextAppendCp(text, 72);
        Model.TextAppendCp(text, 105);
        Model.NodeSetText(nodes, 1, 0, 2);
        Model.NodeAddRegion(nodes, regions, 1, 1, 7200, 9000, 54000, 11000);
        Model.NodeSetConf(nodes, 1, 950);
        Model.NodeAddSrc(nodes, 1, Model.SrText());
        Model.NodeAddSrc(nodes, 1, Model.SrInfer());
        Model.NodeSetAttrInt(nodes, attrs, 1, Model.FkLevel(), 2);
        Model.PageNew(pages, 1, 61200, 79200, 0, Model.PkVector());
        Model.PageSetHealth(pages, 0, 987);
        Model.LedgerAdd(ledger, Model.DrPageNumber(), 1, 29000, 76000, 32200, 77200, 998, Model.SrText());
        return 0;
    }
